function parseAge(input) {
  try {
    const age = Number(input);
    if (Number.isNaN(age)) {
      throw new TypeError(`"${input}" is not a number`);
    }
    if (age < 0 || age > 150) {
      throw new RangeError(`${age} is out of range`);
    }
    return age;
  } catch (error) {
    console.log(`Problem: ${error.message}`);
    return null;
  } finally {
    console.log(`Checked "${input}"`);   // runs before the function returns
  }
}

console.log(parseAge("42"));
console.log(parseAge("abc"));
console.log(parseAge("200"));

