class ValidationError extends Error {
  constructor(message, field) {
    super(message);
    this.name = "ValidationError";
    this.field = field;
  }
}

function register(user) {
  if (!user.email.includes("@")) {
    throw new ValidationError("Email must contain @", "email");
  }
  return "registered";
}

try {
  register({ email: "ada.example.com" });
} catch (error) {
  console.log(error instanceof ValidationError);
  console.log(`${error.name} on ${error.field}: ${error.message}`);
}

